export interface GeneratedImage {
  id: string;
  dataUrl: string;
  prompt: string;
  baseLocation: string;
  chipLabel: string;
  timestamp: number;
  status: 'loading' | 'ready' | 'error';
  mediaId?: string;
}

export interface UtilityChip {
  label: string;
  prefix: string;
}

export interface SuggestionChip {
  label: string;
  promptAddon: string;
  emoji?: string;
}

import { UtilityChip } from './types';

export const UTILITY_CHIPS: UtilityChip[] = [
  { label: 'simple', prefix: 'A simple image of' },
  { label: 'wide shot', prefix: 'A wide angle shot of' },
  { label: 'close up', prefix: 'A close up shot of' },
  { label: 'high angle', prefix: 'A high angle view of' },
  { label: 'low angle', prefix: 'A low angle shot of' },
  { label: 'daytime', prefix: 'A bright daytime shot of' },
  { label: 'nighttime', prefix: 'A dark nighttime shot of' },
];

export const CHIP_ROTATION_INTERVAL = 15000;
export const CHIPS_PER_VIEW = 5;

import { Flow } from 'flow-sdk';
import { SuggestionChip } from '../types';

/**
 * Generates an image using the Flow SDK.
 */
export const generateImage = async (prompt: string, modelDisplayName: string) => {
  console.log(`Generating image with model: ${modelDisplayName}`);
  try {
    const result = await Flow.generate.image({
      prompt,
      modelDisplayName,
      aspectRatio: '16:9'
    });

    return {
      dataUrl: `data:${result.mimeType};base64,${result.base64}`,
      mediaId: result.mediaId
    };
  } catch (error) {
    console.error('Flow.generate.image failed:', error);
    throw error;
  }
};

/**
 * Fetches creative suggestions for a location using Flow's text generation.
 */
export const fetchSuggestions = async (location: string, excludeLabels: string[] = []): Promise<SuggestionChip[]> => {
  const excludeContext = excludeLabels.length > 0 
    ? `Avoid these existing suggestions: ${excludeLabels.join(', ')}.` 
    : '';

  const systemInstruction = `You are a creative director's assistant. Given a location, suggest 8 specific objects, atmospheric details, or sub-locations that would be found there. ${excludeContext}
  Return ONLY a valid JSON array of objects with:
  - "label": short 1-3 words (generally lowercase)
  - "promptAddon": a descriptive phrase
  - "emoji": a relevant single emoji`;

  try {
    const response = await Flow.generate.text(
      `Provide 8 unique suggestions for the location: "${location}"`,
      {
        systemInstruction,
        thinkingLevel: 'low'
      }
    );

    let cleaned = response.text || "[]";
    cleaned = cleaned.replace(/```json|```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (error) {
    console.error('Failed to fetch suggestions:', error);
    return [];
  }
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { SuggestionChip } from '../types';
import { fetchSuggestions } from '../services/ai';

export const useGenerativeChips = (location: string) => {
  const [suggestions, setSuggestions] = useState<SuggestionChip[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const locationRef = useRef(location);

  const loadInitial = useCallback(async (loc: string) => {
    if (!loc) return;
    setIsRefreshing(true);
    const results = await fetchSuggestions(loc, []);
    setSuggestions(results);
    setIsRefreshing(false);
  }, []);

  const loadMore = useCallback(async () => {
    if (!location) return;
    const existingLabels = suggestions.map(s => s.label);

    setSuggestions([]);
    setIsRefreshing(true);

    const results = await fetchSuggestions(location, existingLabels);
    setSuggestions(results);
    setIsRefreshing(false);
  }, [location, suggestions]);

  useEffect(() => {
    if (location !== locationRef.current) {
      setSuggestions([]);
      locationRef.current = location;
      if (location) {
        loadInitial(location);
      }
    }
  }, [location, loadInitial]);

  return { suggestions, isRefreshing, loadMore };
};

import React from 'react';

interface ChipProps {
  emoji?: string;
  label: string;
  onClick: () => void;
  variant?: 'utility' | 'generative';
  disabled?: boolean;
}

export const Chip: React.FC<ChipProps> = ({ emoji, label, onClick, variant = 'utility', disabled }) => {
  const baseStyles = "px-4 py-1.5 rounded-full text-[11px] font-medium transition-all duration-200 whitespace-nowrap active:scale-95 flex items-center gap-2 select-none";
  const variants = {
    utility: "bg-black text-white/80 hover:text-white border border-[#595959] hover:border-white/60",
    generative: "bg-black text-white/80 hover:text-white border border-[#595959] hover:border-white/60"
  };

  return (
    <button 
      onClick={onClick}
      disabled={disabled}
      className={`${baseStyles} ${variants[variant]} ${disabled ? 'opacity-30 cursor-not-allowed' : ''}`}
    >
      {emoji && <span className="text-[13px] leading-none shrink-0">{emoji}</span>}
      <span className="lowercase">{label}</span>
    </button>
  );
};

import React, { useState } from 'react';
import { GeneratedImage } from '../types';
import { Flow } from 'flow-sdk';

export const ImageCard: React.FC<{
  image: GeneratedImage;
  onReFire: (image: GeneratedImage) => void;
}> = ({ image, onReFire }) => {
  const [showFullPrompt, setShowFullPrompt] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const handleDownload = async () => {
    if (image.status !== 'ready' || !image.dataUrl || isSaving) return;

    setIsSaving(true);
    try {
      // Use Flow.save to persist to the user's Media Gallery
      const base64 = image.dataUrl.split(',')[1];
      await Flow.save({
        base64,
        mimeType: 'image/png',
        name: `scene-${image.id}`
      });

      setIsSaved(true);
      setTimeout(() => setIsSaved(false), 2000);
    } catch (error) {
      console.error('Flow.save failed:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const isLoading = image.status === 'loading';
  const isError = image.status === 'error';

  return (
    <div className="flex flex-col group">
      <div className={`relative aspect-video border ${isError ? 'border-red-500/50 bg-red-950/20' : 'border-[#595959] bg-black'} overflow-hidden mb-4 rounded-xl transition-all group-hover:border-white/40`}>
        {isLoading ? (
          <div className="w-full h-full flex flex-col items-center justify-center">
            <span className="text-white/40 text-3xl tracking-widest animate-pulse font-light">...</span>
            <span className="text-[10px] font-medium uppercase tracking-[0.4em] text-white/20 mt-1">Generating</span>
          </div>
        ) : isError ? (
          <div className="w-full h-full flex flex-col items-center justify-center gap-2 text-red-500/70">
            <span className="material-symbols-outlined text-[32px]">error</span>
            <span className="text-[10px] font-medium uppercase tracking-[0.2em]">Generation Failed</span>
          </div>
        ) : (
          <>
            <img 
              src={image.dataUrl} 
              alt={image.prompt} 
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
          </>
        )}
      </div>

      <div className="flex flex-col gap-2 px-1">
        <div className="flex items-start justify-between">
          <div className="flex flex-col">
            <span className="text-[12px] font-medium text-white/90 lowercase">
              {image.chipLabel}
            </span>
            <span className="text-[9px] font-medium text-white/40 uppercase tracking-widest mt-0.5">
              {image.baseLocation}
            </span>
          </div>

          <div className="flex items-center gap-1">
            <button 
              onClick={() => onReFire(image)}
              disabled={isLoading || isError || isSaving}
              className={`flex items-center justify-center p-2 transition-all bg-transparent rounded-full border border-transparent ${(isLoading || isError || isSaving) ? 'text-white/5 cursor-not-allowed' : 'text-white/40 hover:text-white hover:bg-white/10 hover:border-[#595959] active:scale-90'}`}
              title="Regenerate"
            >
              <span className="material-symbols-outlined text-[18px]">refresh</span>
            </button>
            <button 
              onClick={handleDownload}
              disabled={isLoading || isError || isSaving}
              className={`flex items-center justify-center p-2 transition-all bg-transparent rounded-full border border-transparent ${(isLoading || isError || isSaving) ? 'text-white/5 cursor-not-allowed' : (isSaved ? 'text-green-500' : 'text-white/40 hover:text-white hover:bg-white/10 hover:border-[#595959] active:scale-90')}`}
              title="Save to Gallery"
            >
              {isSaving ? (
                <div className="w-[18px] h-[18px] border-2 border-white/20 border-t-white rounded-full animate-spin" />
              ) : (
                <span className="material-symbols-outlined text-[18px]">{isSaved ? 'check_circle' : 'download'}</span>
              )}
            </button>
            <button 
              onClick={() => setShowFullPrompt(!showFullPrompt)}
              className={`flex items-center justify-center p-2 transition-all bg-transparent rounded-full border border-transparent text-white/40 hover:text-white hover:bg-white/10 hover:border-[#595959]`}
              title="Toggle Prompt"
            >
              <span className="material-symbols-outlined text-[18px]">
                {showFullPrompt ? 'keyboard_arrow_up' : 'keyboard_arrow_down'}
              </span>
            </button>
          </div>
        </div>

        {showFullPrompt && (
          <div className="pt-2 pb-1 animate-in fade-in slide-in-from-top-1 duration-200">
            <p className="text-white/60 text-[13px] leading-relaxed font-normal">
              Prompt: {image.prompt}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { GeneratedImage, UtilityChip, SuggestionChip } from './types';
import { UTILITY_CHIPS } from './constants';
import { generateImage } from './services/ai';
import { Chip } from './components/Chip';
import { ImageCard } from './components/ImageCard';
import { useGenerativeChips } from './hooks/useGenerativeChips';

export default function App() {
  const [baseLocation, setBaseLocation] = useState('');
  const [activeLocation, setActiveLocation] = useState('');
  const [feed, setFeed] = useState<GeneratedImage[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const { suggestions, isRefreshing, loadMore } = useGenerativeChips(activeLocation);

  useEffect(() => {
    const fontId = 'google-fonts-design-system';
    if (!document.getElementById(fontId)) {
      const preconnect1 = document.createElement('link');
      preconnect1.rel = 'preconnect';
      preconnect1.href = 'https://fonts.googleapis.com';
      document.head.appendChild(preconnect1);

      const preconnect2 = document.createElement('link');
      preconnect2.rel = 'preconnect';
      preconnect2.href = 'https://fonts.gstatic.com';
      preconnect2.crossOrigin = 'anonymous';
      document.head.appendChild(preconnect2);

      const fontLink = document.createElement('link');
      fontLink.id = fontId;
      fontLink.rel = 'stylesheet';
      fontLink.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&display=swap';
      document.head.appendChild(fontLink);

      const iconLink = document.createElement('link');
      iconLink.rel = 'stylesheet';
      iconLink.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0';
      document.head.appendChild(iconLink);
    }

    const styleId = 'flow-app-styles';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        html, body, #root { 
          margin: 0; padding: 0; width: 100%; height: 100%; 
          background: #000000; 
          font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; 
          letter-spacing: 0.1px; 
          -webkit-font-smoothing: antialiased; 
        }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #7a7a7a; }
      `;
      document.head.appendChild(style);
    }
  }, []);

  const handleFire = useCallback(async (label: string, prefix: string) => {
    const targetLocation = activeLocation || baseLocation;
    if (!targetLocation) return;

    const id = crypto.randomUUID();
    const fullPrompt = `${prefix} ${targetLocation}.`.trim();

    const placeholder: GeneratedImage = {
      id,
      dataUrl: '',
      prompt: fullPrompt,
      baseLocation: targetLocation,
      chipLabel: label,
      timestamp: Date.now(),
      status: 'loading'
    };

    setFeed(prev => [placeholder, ...prev]);
    setIsGenerating(true);

    try {
      // Always use Nano Banana 2 as requested
      const result = await generateImage(fullPrompt, 'Nano Banana 2');
      setFeed(prev => prev.map(img => 
        img.id === id 
          ? { ...img, dataUrl: result.dataUrl, mediaId: result.mediaId, status: 'ready' as const }
          : img
      ));
    } catch (error) {
      console.error('Generation Error in App:', error);
      setFeed(prev => prev.map(img => 
        img.id === id ? { ...img, status: 'error' as const } : img
      ));
    } finally {
      setFeed(currentFeed => {
        const stillLoading = currentFeed.some(img => img.status === 'loading');
        if (!stillLoading) setIsGenerating(false);
        return currentFeed;
      });
    }
  }, [activeLocation, baseLocation]);

  const handleReset = () => {
    if (confirm('Clear entire session? This will delete all generated sketches.')) {
      setBaseLocation('');
      setActiveLocation('');
      setFeed([]);
    }
  };

  const handleUtilityClick = (chip: UtilityChip) => {
    handleFire(chip.label, chip.prefix);
  };

  const handleGenerativeClick = (chip: SuggestionChip) => {
    const displayLabel = chip.emoji ? `${chip.emoji} ${chip.label}` : chip.label;
    handleFire(displayLabel, `A shot of ${chip.promptAddon} in`);
  };

  const submitLocation = () => {
    if (baseLocation.trim()) {
      setActiveLocation(baseLocation);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submitLocation();
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen bg-black text-[#ffffff] font-['Google_Sans_Text'] selection:bg-zinc-800 overflow-hidden">
      <aside className="w-full md:w-[380px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#595959] flex flex-col bg-black">
        <div className="flex flex-col flex-1 overflow-hidden">
          {/* Top section: Input */}
          <div className="p-6">
            <div className="relative border border-[#595959] rounded-2xl bg-black transition-all focus-within:border-white/60 p-3 pt-4">
              <textarea 
                ref={textareaRef}
                value={baseLocation}
                onChange={(e) => setBaseLocation(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Describe location (e.g. 1980s suburbs) ..."
                className="w-full h-[52px] bg-transparent text-lg leading-snug tracking-tight outline-none text-white placeholder:text-white/40 resize-none border-none p-0 custom-scrollbar"
              />
              <button 
                onClick={submitLocation}
                className="absolute bottom-2 right-2 p-1.5 text-white/40 hover:text-white transition-colors flex items-center justify-center active:scale-90"
              >
                <span className="material-symbols-outlined text-[24px]">arrow_forward</span>
              </button>
            </div>
          </div>

          {/* Middle section: Scrollable chips */}
          <div className="flex-1 overflow-y-auto custom-scrollbar px-6 pb-2 space-y-8">
            {activeLocation ? (
              <div className="space-y-8 pt-2">
                <div className="space-y-4">
                  <h3 className="text-[11px] font-medium text-white/70 px-1">Basic shots</h3>
                  <div className="flex flex-wrap gap-2">
                    {UTILITY_CHIPS.map(chip => (
                      <Chip 
                        key={chip.label} 
                        label={chip.label} 
                        onClick={() => handleUtilityClick(chip)}
                      />
                    ))}
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="px-1">
                    <h3 className="text-[11px] font-medium text-white/70">Things you might see</h3>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {isRefreshing && suggestions.length === 0 ? (
                      <div className="flex gap-2">
                        {[1, 2, 3].map(i => (
                          <div key={i} className="h-8 w-20 bg-black border border-[#595959] animate-pulse rounded-full" />
                        ))}
                      </div>
                    ) : (
                      <>
                        {suggestions.map((chip, idx) => (
                          <Chip 
                            key={`${chip.label}-${idx}`}
                            emoji={chip.emoji}
                            label={chip.label} 
                            variant="generative" 
                            onClick={() => handleGenerativeClick(chip)}
                          />
                        ))}
                        {!isRefreshing && suggestions.length > 0 && (
                          <Chip 
                            label="more ideas ..."
                            emoji="🎲"
                            onClick={loadMore}
                            variant="generative"
                          />
                        )}
                        {isRefreshing && suggestions.length > 0 && (
                           <Chip 
                            label="more ideas ..."
                            emoji="🎲"
                            onClick={() => {}}
                            variant="generative"
                            disabled
                          />
                        )}
                      </>
                    )}
                  </div>
                </div>
              </div>
            ) : (
              <div className="h-full flex items-center justify-center py-12">
                <p className="text-[10px] font-medium uppercase tracking-[0.4em] text-white/10 text-center leading-loose">
                  ENTER A LOCATION<br/>TO UNLOCK OPTIONS
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Bottom Bar: Reset only */}
        <div className="px-6 pb-8 pt-4 bg-black">
          <button 
            onClick={handleReset}
            className="w-full h-[34px] flex items-center justify-center gap-2 rounded-full border border-[#595959] text-[10px] font-medium uppercase tracking-widest text-white/40 hover:text-white transition-all active:scale-95"
          >
            <span className="material-symbols-outlined text-[16px]">restart_alt</span>
            <span>RESET</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto bg-black custom-scrollbar">
        <div className="max-w-5xl mx-auto px-6 pt-6 pb-20 min-h-full flex flex-col">
          {feed.length === 0 ? (
            <div className="flex-1 flex flex-col items-center justify-center opacity-10 py-32">
              <p className="text-[12px] font-medium uppercase tracking-[0.8em]">SCENE CANVAS READY</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-x-12 gap-y-16 pb-32">
              {feed.map((image) => (
                <ImageCard 
                  key={image.id} 
                  image={image} 
                  onReFire={(img: GeneratedImage) => handleFire(img.chipLabel, img.prompt)}
                />
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
